startup:
if [ ! -f /home/container/Caddyfile ]; then echo "server {
    listen ${SERVER_PORT:-80}
    root * /home/container/www
    file_server
}" > /home/container/Caddyfile; mkdir -p /home/container/www; echo '<!DOCTYPE html><html><body><h1>Caddy is running!</h1></body></html>' > /home/container/www/index.html; fi; exec caddy run --config /home/container/Caddyfile --adapter caddyfile
